/*
 * __NAME__: a clip-backed avatar. Muse's own animation, played back frame by
 * frame on the 64x64 pixel grid instead of being drawn procedurally.
 *
 * Generated by gif2pixel.py on __DATE__ from:
__SOURCES__
 * Options: __OPTIONS__
 *
 * Clips: __CLIPLIST__
 * Shared palette: __NCOLORS__ colours, the black background (index 0) and
 * __NFX__ effect colours. Frame data: __DATABYTES__ bytes of const 8-bit indices
 * (PackBits where smaller); __TOTALBYTES__ bytes of const data in all. RAM:
 * a 4 KB framebuffer, the 512-byte screen map and a 1 KB RGB565 palette
 * (static, zero-initialised; no malloc).
 *
 * Behaviour: each mode plays its clip, looping on mode_t with the clip's own
 * frame times. Boot plays once and carries on into idle; off plays once and
 * holds. Thinking without its own clip plays working, and working without
 * its own plays thinking. Any other missing clip is idle, with a cheap
 * effect drawn only on background cells: listening adds expanding dotted
 * rings, speaking bounces with the voice (muse_speaking.h), error tints red,
 * shakes and shows "!", boot fades in, off dims. Speaking with its own clip:
 * __SPEAK__. Petting (happy) plays the happy clip (__HAPPYDESC__),
 * or hops if there is none.
 *
 * Do not edit by hand: re-run gif2pixel.py.
 */

#include "muse_pixel.h"
#include "muse_speaking.h"

#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#define W MUSE_PX_W
#define H MUSE_PX_H
#define TAU 6.2831853f

#if MUSE_PX_W != 64 || MUSE_PX_H != 64
#error "frames were converted for a 64x64 grid"
#endif

/* ---------------------------------------------------------------------------
 * Generated data (all const: flash, or PSRAM with CONFIG_SPIRAM_RODATA)
 * ------------------------------------------------------------------------- */

/* Index 0 is the background; the last FX_COUNT entries are the effects'. */
#define GIF_COLORS __PALN__
static const uint8_t GIF_PAL[GIF_COLORS][3] = {
__PALETTE__
};

enum { FX_LISTEN, FX_LISTEN_DIM, FX_SPEAK, FX_ERROR, FX_COUNT };
#define FX_BASE (GIF_COLORS - FX_COUNT)

/* All frames' 64x64 indices; a frame of exactly W * H bytes is raw. */
static const uint8_t GIF_DATA[__DATALEN__] = {
__DATA__
};

typedef struct {
    uint32_t off;   /* into GIF_DATA */
    uint16_t len;   /* bytes; W * H means raw, else PackBits */
    uint16_t ms;    /* how long it shows */
} gif_frame_t;

static const gif_frame_t GIF_FRAMES[__NFRAMES__] = {
__FRAMES__
};

enum { CLIP_BOOT, CLIP_IDLE, CLIP_LISTENING, CLIP_THINKING, CLIP_WORKING, CLIP_SPEAKING, CLIP_HAPPY,
       CLIP_ERROR, CLIP_OFF, CLIP_COUNT };

typedef struct {
    uint16_t first, count;   /* count 0: no such clip */
    uint32_t total_ms;
    bool once;               /* play once rather than loop */
} gif_clip_t;

static const gif_clip_t GIF_CLIPS[CLIP_COUNT] = {
__CLIPS__
};

/* Speaking with its own clip. 0: as is; 1: bounce with the voice; 2: frame chosen by the voice. */
#define SPEAK_STYLE __SPEAKSTYLE__
#define SPEAK_BOUNCE __SPEAKBOUNCE__f   /* cells */
#define SPEAK_PULSE __SPEAKPULSE__f    /* brightness gain with the voice when idle stands in */
#define HOP_CELLS __HOP__f              /* happy hop height when there is no happy clip */
#define EFFECTS __EFFECTS__                 /* effects on idle for missing clips */
#define HAPPY_HOLD __HAPPYHOLD__              /* 1: a pet plays the happy clip once through */
/* Where the avatar sits in the grid, for the effects. */
#define AV_CX __AVCX__f
#define AV_CY __AVCY__f
#define AV_R __AVR__f                   /* rings start here */

/* ---------------------------------------------------------------------------
 * Accents (the default avatar's)
 * ------------------------------------------------------------------------- */

static const uint32_t ACCENTS[MUSE_MODE_COUNT] = {
__ACCENTS__
};

uint32_t muse_pixel_accent(muse_mode_t mode)
{
    return ACCENTS[(unsigned)mode < MUSE_MODE_COUNT ? mode : MUSE_MODE_IDLE];
}

uint32_t muse_pixel_working_accent(void)
{
    return __WORKINGACCENT__;
}

/* ---------------------------------------------------------------------------
 * State (zero-initialised statics only: initialised data would stay internal)
 * ------------------------------------------------------------------------- */

static uint8_t s_fb[W * H];
static uint16_t s_pal[256];
static uint16_t s_pal_dim[256];
static int s_pal_key;   /* brightness and tint the palette was built for, + 1; 0: not yet */

static inline uint16_t rgb565(int r, int g, int b)
{
    return (uint16_t)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));
}

/* Brightness and red tint in 1/32 steps (32, 0: the clip's own colours; up to 48 brightens). */
static void build_palette(int level, int tint)
{
    int key = level * 64 + tint + 1;
    if (key == s_pal_key) {
        return;
    }
    s_pal_key = key;
    for (int i = 0; i < GIF_COLORS; i++) {
        int r = GIF_PAL[i][0], g = GIF_PAL[i][1], b = GIF_PAL[i][2];
        if (tint && i > 0 && i < FX_BASE) {
            /* Error: luminance pushed towards red. */
            int y = (r * 77 + g * 150 + b * 29) >> 8;
            r += ((y / 2 + 128) - r) * tint / 32;
            g += ((y / 3) - g) * tint / 32;
            b += ((y / 3) - b) * tint / 32;
        }
        r = r * level / 32;
        g = g * level / 32;
        b = b * level / 32;
        r = r > 255 ? 255 : r;
        g = g > 255 ? 255 : g;
        b = b > 255 ? 255 : b;
        s_pal[i] = rgb565(r, g, b);
        /* The block edge shade gives the enlarged pixels a faint grid texture (0.72x). */
        s_pal_dim[i] = rgb565(r * 184 / 256, g * 184 / 256, b * 184 / 256);
    }
}

static inline float clampf(float v, float lo, float hi)
{
    return v < lo ? lo : (v > hi ? hi : v);
}

static inline int iround(float v)
{
    return (int)floorf(v + 0.5f);
}

/* Decode a frame into s_fb. Bounded on both ends whatever the data says. */
static void unpack(const gif_frame_t *f)
{
    const uint8_t *src = &GIF_DATA[f->off];
    uint32_t len = f->len;
    if (len == W * H) {
        memcpy(s_fb, src, W * H);
        return;
    }
    uint32_t i = 0, o = 0;
    while (i < len && o < W * H) {
        uint8_t c = src[i++];
        uint32_t n;
        if (c & 0x80) {
            n = (uint32_t)(c & 0x7f) + 2;
            if (i >= len) {
                break;
            }
            uint8_t v = src[i++];
            if (n > W * H - o) {
                n = W * H - o;
            }
            memset(&s_fb[o], v, n);
        } else {
            n = (uint32_t)c + 1;
            if (n > len - i) {
                n = len - i;
            }
            if (n > W * H - o) {
                n = W * H - o;
            }
            memcpy(&s_fb[o], &src[i], n);
            i += n;
        }
        o += n;
    }
    if (o < W * H) {
        memset(&s_fb[o], 0, W * H - o);
    }
}

/* Move the frame by (dx, dy) cells, filling with background. */
static void shift(int dx, int dy)
{
    if (dx <= -W || dx >= W || dy <= -H || dy >= H) {
        memset(s_fb, 0, sizeof(s_fb));
        return;
    }
    if (dy < 0) {
        memmove(s_fb, &s_fb[-dy * W], (size_t)(H + dy) * W);
        memset(&s_fb[(H + dy) * W], 0, (size_t)(-dy) * W);
    } else if (dy > 0) {
        memmove(&s_fb[dy * W], s_fb, (size_t)(H - dy) * W);
        memset(s_fb, 0, (size_t)dy * W);
    }
    if (dx) {
        for (int y = 0; y < H; y++) {
            uint8_t *row = &s_fb[y * W];
            if (dx > 0) {
                memmove(&row[dx], row, (size_t)(W - dx));
                memset(row, 0, (size_t)dx);
            } else {
                memmove(row, &row[-dx], (size_t)(W + dx));
                memset(&row[W + dx], 0, (size_t)(-dx));
            }
        }
    }
}

/* ---------------------------------------------------------------------------
 * Effects: a few cells per frame, only on background so they sit behind
 * ------------------------------------------------------------------------- */

static inline void behind(int x, int y, uint8_t c)
{
    if ((unsigned)x < W && (unsigned)y < H && s_fb[y * W + x] == 0) {
        s_fb[y * W + x] = c;
    }
}

static void ring(float r, int dots, float phase, uint8_t c)
{
    for (int i = 0; i < dots; i++) {
        float a = phase + i * (TAU / dots);
        behind(iround(AV_CX + r * cosf(a)), iround(AV_CY + r * sinf(a)), c);
    }
}

/* Listening: two sparse dotted rings drifting outwards and fading, a little
 * faster with the voice. */
static void fx_listening(float t, float level)
{
    for (int k = 0; k < 2; k++) {
        float u = t * (0.6f + level * 0.5f) + k * 0.5f;
        u -= floorf(u);
        if (u > 0.8f) {
            continue;   /* faded out */
        }
        float r = AV_R + u * (34.0f - AV_R);
        uint8_t c = FX_BASE + (u < 0.4f ? FX_LISTEN : FX_LISTEN_DIM);
        ring(r, 10 + (int)(r * 0.45f), k * 0.4f + t * 0.3f, c);
    }
}

/* Speaking: a ring that swells with the mouth. */
static void fx_speaking(float mouth, float t)
{
    if (mouth > 0.08f) {
        float r = AV_R + 2.0f + mouth * 7.0f;
        ring(r, 10 + (int)(r * 0.45f), t * 0.5f, FX_BASE + FX_SPEAK);
    }
}

/* Error: a "!" at the top right. */
static void fx_error(void)
{
    static const char *const BANG[] = { ".##.", ".##.", ".##.", ".##.", ".##.", "....", ".##.", };
    for (int y = 0; y < 7; y++) {
        for (int x = 0; x < 4; x++) {
            if (BANG[y][x] == '#') {
                s_fb[(4 + y) * W + 54 + x] = FX_BASE + FX_ERROR;
            }
        }
    }
}

/* ---------------------------------------------------------------------------
 * Clips
 * ------------------------------------------------------------------------- */

static inline bool has(int clip)
{
    return GIF_CLIPS[clip].count > 0;
}

/* The frame of `clip` that shows `secs` into it (looping unless once). */
static int frame_at(int clip, float secs, bool *done)
{
    const gif_clip_t *c = &GIF_CLIPS[clip];
    uint32_t ms = secs > 0 ? (uint32_t)(secs * 1000.0f + 0.5f) : 0;
    *done = false;
    if (c->total_ms == 0) {
        return c->first;
    }
    if (ms >= c->total_ms) {
        if (c->once) {
            *done = true;
            return c->first + c->count - 1;
        }
        ms %= c->total_ms;
    }
    for (int i = 0; i < c->count; i++) {
        uint32_t d = GIF_FRAMES[c->first + i].ms;
        if (ms < d) {
            return c->first + i;
        }
        ms -= d;
    }
    return c->first + c->count - 1;
}

static int mode_clip(muse_mode_t mode, bool working)
{
    switch (mode) {
    case MUSE_MODE_BOOT:
        return has(CLIP_BOOT) ? CLIP_BOOT : CLIP_IDLE;
    case MUSE_MODE_LISTENING:
        return has(CLIP_LISTENING) ? CLIP_LISTENING : CLIP_IDLE;
    case MUSE_MODE_THINKING:
        if (working && has(CLIP_WORKING)) return CLIP_WORKING;
        if (has(CLIP_THINKING)) return CLIP_THINKING;
        return has(CLIP_WORKING) ? CLIP_WORKING : CLIP_IDLE;
    case MUSE_MODE_SPEAKING:
        return has(CLIP_SPEAKING) ? CLIP_SPEAKING : CLIP_IDLE;
    case MUSE_MODE_ERROR:
        return has(CLIP_ERROR) ? CLIP_ERROR : CLIP_IDLE;
    case MUSE_MODE_OFF:
        return has(CLIP_OFF) ? CLIP_OFF : CLIP_IDLE;
    default:
        return CLIP_IDLE;
    }
}

/* ---------------------------------------------------------------------------
 * Render
 * ------------------------------------------------------------------------- */

void muse_pixel_render(const muse_pose_t *p)
{
    static muse_speaking_t speech;
    static float s_last_t;
    static bool s_started, s_happy_on, s_happy_play;
    static float s_happy_t0;
    static muse_mode_t s_happy_mode;

    float dt = s_started ? clampf(p->t - s_last_t, 0, 0.2f) : 0.04f;
    s_last_t = p->t;
    s_started = true;

    muse_mode_t mode = (unsigned)p->mode < MUSE_MODE_COUNT ? p->mode : MUSE_MODE_IDLE;
    bool working = mode == MUSE_MODE_THINKING && p->working > 0.5f;
    float happy = mode == MUSE_MODE_ERROR ? 0 : p->happy;
    bool speaking = mode == MUSE_MODE_SPEAKING;
    muse_speaking_update(&speech, speaking, dt, p->mode_t, p->level);

    if (happy > 0) {
        if (!s_happy_on) {
            s_happy_on = true;
            s_happy_play = true;
            s_happy_t0 = p->t;
            s_happy_mode = mode;
        }
    } else {
        s_happy_on = false;
    }

    int clip = mode_clip(mode, working);
    float secs = p->mode_t;
    /* The happy clip plays while petted, and with HAPPY_HOLD on to its end unless the mode changes. */
    bool happy_clip = has(CLIP_HAPPY) && mode != MUSE_MODE_ERROR &&
                      (happy > 0 || (HAPPY_HOLD && s_happy_play && mode == s_happy_mode &&
                                     p->t - s_happy_t0 < GIF_CLIPS[CLIP_HAPPY].total_ms / 1000.0f));
    if (!happy_clip) {
        s_happy_play = false;
    }
    if (happy_clip) {
        clip = CLIP_HAPPY;
        secs = p->t - s_happy_t0;
    }
    /* A mode shown by idle (its own clip missing) gets its effect. */
    bool stand_in = !happy_clip && clip == CLIP_IDLE && mode != MUSE_MODE_IDLE;

    bool done;
    int frame = frame_at(clip, secs, &done);
    if (done && clip == CLIP_BOOT) {
        /* Boot played: carry on into idle. */
        frame = frame_at(CLIP_IDLE, secs - GIF_CLIPS[CLIP_BOOT].total_ms / 1000.0f, &done);
    }
    if (SPEAK_STYLE == 2 && speaking && clip == CLIP_SPEAKING) {
        /* Speaking frames in order of openness, picked by the mouth. */
        const gif_clip_t *c = &GIF_CLIPS[CLIP_SPEAKING];
        frame = c->first + iround(clampf(speech.mouth, 0, 1) * (c->count - 1));
    }
    unpack(&GIF_FRAMES[frame]);

    /* ---- whole-image motion, in cells ---- */
    float dx = 0, dy = 0;
    if (speaking && !happy_clip && (clip != CLIP_SPEAKING || SPEAK_STYLE == 1)) {
        dy -= speech.mouth * SPEAK_BOUNCE;
    }
    if (happy > 0 && !happy_clip) {
        dy -= fabsf(sinf(p->t * 9.0f)) * HOP_CELLS * happy;
    }
    if (EFFECTS && stand_in && mode == MUSE_MODE_ERROR && p->mode_t < 0.6f) {
        dx = sinf(p->t * 18.0f) * 1.0f;
    }
    int ix = iround(dx), iy = iround(dy);
    if (ix || iy) {
        shift(ix, iy);
    }

    /* ---- effects, brightness and tint for stand-ins ---- */
    float bright = 1.0f;
    int tint = 0;
    if (EFFECTS && stand_in) {
        switch (mode) {
        case MUSE_MODE_LISTENING:
            fx_listening(p->mode_t, p->level);
            break;
        case MUSE_MODE_SPEAKING:
            fx_speaking(speech.mouth, p->t);
            bright = 1.0f + SPEAK_PULSE * clampf(speech.mouth, 0, 1);
            break;
        case MUSE_MODE_ERROR:
            fx_error();
            tint = 12;
            break;
        case MUSE_MODE_BOOT:
            bright = clampf(p->mode_t / 0.6f, 0, 1);
            break;
        case MUSE_MODE_OFF:
            bright = 1.0f - 0.7f * clampf(p->mode_t / 1.0f, 0, 1);
            break;
        default:
            break;
        }
    }
    build_palette(iround(clampf(bright, 0, 1.5f) * 32), tint);
}

/* ---------------------------------------------------------------------------
 * Scale (as the default avatar's)
 * ------------------------------------------------------------------------- */

/*
 * Screen pixel -> grid cell, with 0x80 set on a cell's last screen pixel. When
 * cells are 3+ pixels, that edge is drawn dimmer so the pixel grid shows.
 */
#define MAP_MAX 512
static uint8_t s_map[MAP_MAX];
static int s_size;

void muse_pixel_set_size(int px)
{
    s_size = px < MAP_MAX ? px : MAP_MAX;
    bool grid = s_size >= 3 * W;
    for (int i = 0; i < s_size; i++) {
        int cell = i * W / s_size;
        bool edge = grid && (i + 1) * W / s_size != cell;
        s_map[i] = (uint8_t)(cell | (edge ? 0x80 : 0));
    }
}

void muse_pixel_scale(uint16_t *dst, int stride_px, int x0, int x1, int y0, int y1)
{
    int n = x1 - x0 + 1;
    const uint8_t *xmap = &s_map[x0];
    const uint16_t *prev = NULL;
    uint8_t prev_m = 0;
    for (int y = y0; y <= y1; y++, dst += stride_px) {
        uint8_t m = s_map[y];
        if (prev && m == prev_m) {
            memcpy(dst, prev, n * sizeof(uint16_t));
            continue;
        }
        const uint8_t *row = &s_fb[(m & 0x7f) * W];
        if (m & 0x80) {
            for (int i = 0; i < n; i++) {
                dst[i] = s_pal_dim[row[xmap[i] & 0x7f]];
            }
        } else {
            for (int i = 0; i < n; i++) {
                uint8_t xm = xmap[i];
                uint8_t c = row[xm & 0x7f];
                dst[i] = xm & 0x80 ? s_pal_dim[c] : s_pal[c];
            }
        }
        prev = dst;
        prev_m = m;
    }
}
